 fn commands(&mut self,i:Identity,c:Commands)->Result<(),Error>{let b=self.bm(i)?;b.controls=c.controls;b.aim=c.aim;b.current_target=c.target;b.hold=c.hold;b.firing=c.firing;self.manual.retain(|id|*id!=i);if !c.ai{self.manual.push(i);}Ok(())}
 fn pose(&mut self,i:Identity,p:Vec2,previous:Vec2,v:Vec2,docked:bool)->Result<(),Error>{let b=self.bm(i)?;b.pos=p;b.prev=previous;b.vel=v;b.docked=docked;Ok(())}
 fn remove_craft(&mut self,i:Identity,r:Removal)->Result<(),Error>{let b=self.bm(i)?;match r{Removal::Detached=>b.wing=None,Removal::CarrierRetreated=>b.retreated=true,Removal::CarrierDestroyed=>{b.dead=true;b.hp=0.0;},_=>{}}Ok(())}
