 fn aim(&self,i:Identity,h:u32,g:u32,t:Target)->Result<Aim,Error>{let b=self.body(i)?;let m=self.mounts(i)?.into_iter().find(|m|m.handle==h&&m.generation==g).ok_or(Error::StaleIdentity)?;let(p,v,r)=match t{Target::Ship(i)=>{let x=self.body(i)?;(x.pos,x.vel,x.spec.radius)},Target::Missile(i)=>{let x=self.projectiles.iter().find(|p|p.identity==i).ok_or(Error::StaleIdentity)?;(x.pos,x.vel,x.radius)}};let vx=v.x-b.vel.x;let vy=v.y-b.vel.y;let px=p.x-b.pos.x;let py=p.y-b.pos.y;let time=if m.guided{fire_control::intercept_time(px,py,vx,vy,900.0)}else{Some(0.0)};let Some(time)=time else{return Ok(Aim::default());};let point=Vec2{x:b.pos.x+px+vx*time,y:b.pos.y+py+vy*time};let predicted=Some(point);let dx=point.x-b.pos.x;let dy=point.y-b.pos.y;let distance=defense_ai::frame_length(dx,dy);let angle=dy.atan2(dx);let end=Vec2{x:b.pos.x+angle.cos()*m.range,y:b.pos.y+angle.sin()*m.range};let contact=if m.guided{true}else{match t{Target::Ship(target)=>{let target=self.body(target)?;fire_control::hull(&fire_control::Body{x:target.pos.x,y:target.pos.y,facing:target.facing,radius:target.spec.radius,hull:target.spec.bounds.iter().map(|v|[v.x,v.y]).collect(),..Default::default()},b.pos.x,b.pos.y,end.x,end.y).is_some()},Target::Missile(_)=>fire_control::circle(b.pos.x,b.pos.y,end.x,end.y,p.x,p.y,r+3.0).is_some()}};Ok(Aim{predicted,solved:if distance<=m.range+r&&contact{Some(point)}else{None}})}
