 fn fire_roster(&self)->Result<Vec<Identity>,Error>{Ok(self.roster.clone())}
 fn enqueue_ship_step(&mut self,i:Identity,dt:f64,t:Option<Identity>,p:FirePermission)->Result<(),Error>{self.queued.push((i,dt,t,p));Ok(())}
